    _,dl=spectrum(p)
    # cluster
    out=[];i=0
    while i<len(dl):
        j=i
        while j+1<len(dl) and abs(dl[j+1]-dl[i])<1e-3: j+=1
        if j-i+1==3: out.append(dl[i])
